/**
 * LLM gateway: `/gw/<providerId>/<path>` forwards an agent's request to a configured provider.
 *
 * The agent authenticates with its gateway token (models.yml generated by agent/config.ts); the gateway checks the
 * token and the provider switches, then replaces the token with the real key and streams the upstream response
 * back. Provider keys therefore never reach the agent.
 */
import type { Provider } from "@pikvm/chat-protocol";
import { authHeaderFor, keyFromRequest, resolveEndpoint, verifyGatewayToken } from "../agent/providers.ts";
import { isModelAllowed } from "../models/policy.ts";
import { resolveSetting } from "../settings/store.ts";

const DROP_REQUEST = new Set([
    "host",
    "authorization",
    "x-api-key",
    "x-goog-api-key",
    "cookie",
    "content-length",
    "connection",
    "accept-encoding",
]);
// fetch() decodes the body, so encoding and length headers from upstream no longer apply.
const DROP_RESPONSE = new Set(["content-encoding", "content-length", "transfer-encoding", "connection", "set-cookie"]);

function fail(status: number, message: string): Response {
    return Response.json({ error: { type: "gateway_error", message } }, { status });
}

/** Model named in the request, for policy checks: JSON `model` field or Gemini-style `/models/<id>:`. */
function requestedModel(path: string, body: Uint8Array | undefined): string | undefined {
    if (body?.length) {
        try {
            const m = (JSON.parse(new TextDecoder().decode(body)) as { model?: unknown }).model;
            if (typeof m === "string") return m;
        } catch {}
    }
    return path.match(/\/models\/([^/:]+)[:/]/)?.[1];
}

export async function handleGateway(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const [, , providerId, ...rest] = url.pathname.split("/");
    if (!providerId) return fail(404, "Unknown provider");

    const userId = verifyGatewayToken(keyFromRequest(req.headers));
    if (!userId) return fail(401, "Invalid gateway token");

    // Every provider is proxied: the agent never holds a provider key.
    const provider = (resolveSetting("agent.providers", userId).value as Record<string, Provider>)[providerId];
    if (!provider?.enabled) return fail(404, `Provider ${providerId} is not available`);
    const ep = resolveEndpoint(providerId, provider);
    if (!ep) return fail(502, `Provider ${providerId} has no endpoint configured`);

    const body = req.method === "GET" || req.method === "HEAD" ? undefined : new Uint8Array(await req.arrayBuffer());
    const path = `/${rest.join("/")}`;
    const model = requestedModel(path, body);
    if (model && !isModelAllowed(userId, `${providerId}/${model}`)) {
        return fail(403, `The model ${providerId}/${model} is not allowed`);
    }

    const headers = new Headers();
    for (const [k, v] of req.headers) if (!DROP_REQUEST.has(k.toLowerCase())) headers.set(k, v);
    for (const [k, v] of Object.entries(provider.headers ?? {})) headers.set(k, v);
    if (provider.apiKey) for (const [k, v] of Object.entries(authHeaderFor(ep.api, provider.apiKey))) headers.set(k, v);

    let upstream: Response;
    try {
        upstream = await fetch(`${ep.baseUrl}${path}${url.search}`, {
            method: req.method,
            headers,
            body,
            signal: req.signal,
        });
    } catch (err) {
        return fail(502, `Upstream request failed: ${(err as Error).message}`);
    }
    const out = new Headers();
    for (const [k, v] of upstream.headers) if (!DROP_RESPONSE.has(k.toLowerCase())) out.set(k, v);
    return new Response(upstream.body, { status: upstream.status, statusText: upstream.statusText, headers: out });
}
